const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);
    useLayoutEffect(() => {
        if (dashed && ref.current) ref.current.computeLineDistances();
    }, [geometry, dashed]);
    return (
        <line ref={ref as any} geometry={geometry}>
            {dashed ? ( <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> ) : ( <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> )}
        </line>
    );
};

const DimensionTick: React.FC<{ position: THREE.Vector3; direction: THREE.Vector3; color: string }> = ({ position, direction, color }) => {
    const TICK_SIZE = 0.05;
    const up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(direction.dot(up)) > 0.9) {
        up.set(1, 0, 0);
    }
    const right = new THREE.Vector3().crossVectors(direction, up).normalize();
    const tickVec = new THREE.Vector3().addVectors(direction, right).normalize().multiplyScalar(TICK_SIZE);

    const p1 = position.clone().sub(tickVec);
    const p2 = position.clone().add(tickVec);

    return <SimpleLine points={[p1, p2]} color={color} lineWidth={2} depthTest={false} />;
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue, tool, updateShape } = useApp();
    const { camera, gl } = useThree();
    const [dragP3, setDragP3] = useState<THREE.Vector3 | null>(null);
    const draggingRef = useRef(false);
    const rafRef = useRef<number | null>(null);

    if (!shape.points || shape.points.length < 3) return null;

    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);

    const p3Source = dragP3 || new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);

    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3Source, p1);

    const lenSq = v12.lengthSq();
    const projectionFactor = lenSq > 0 ? v13.dot(v12) / lenSq : 0;
    const projectedPointOnLine = p1.clone().add(v12.clone().multiplyScalar(projectionFactor));
    const offsetVector = new THREE.Vector3().subVectors(p3Source, projectedPointOnLine);

    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);

    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const dimDir = new THREE.Vector3().subVectors(dimEnd, dimStart).normalize();

    const GAP_SIZE = 0.05; 
    const EXTENSION_OVERSHOOT = 0.05;

    const offsetDir = offsetVector.clone().normalize();
    const offsetLen = offsetVector.length();

    const useExtensions = offsetLen > GAP_SIZE * 2;

    const ext1Start = useExtensions ? p1.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p1;
    const ext2Start = useExtensions ? p2.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p2;

    const ext1End = dimStart.clone().add(offsetDir.clone().multiplyScalar(EXTENSION_OVERSHOOT));
    const ext2End = dimEnd.clone().add(offsetDir.clone().multiplyScalar(EXTENSION_OVERSHOOT));

    const color = isSelected ? '#3b82f6' : (shape.color || '#000000');
    const extensionColor = isSelected ? '#3b82f6' : '#666666';

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT && isSelected && e.button === 0) {
            e.stopPropagation();
            draggingRef.current = true;
            document.body.style.cursor = 'grabbing';

            const handleWindowMove = (ev: PointerEvent) => {
                if (!draggingRef.current) return;

                if (rafRef.current) cancelAnimationFrame(rafRef.current);
                rafRef.current = requestAnimationFrame(() => {
                    const raycaster = new THREE.Raycaster();
                    const ndc = new THREE.Vector2(
                        (ev.clientX / gl.domElement.clientWidth) * 2 - 1,
                        -(ev.clientY / gl.domElement.clientHeight) * 2 + 1
                    );
                    raycaster.setFromCamera(ndc, camera);

                    const planeY = p1.y;
                    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
                    const target = new THREE.Vector3();

                    if (raycaster.ray.intersectPlane(plane, target)) {
                        setDragP3(target);
                    }
                });
            };

            const handleWindowUp = () => {
                if (draggingRef.current) {
                    draggingRef.current = false;
                    document.body.style.cursor = 'default';
                    window.removeEventListener('pointermove', handleWindowMove);
                    window.removeEventListener('pointerup', handleWindowUp);
                    if (rafRef.current) cancelAnimationFrame(rafRef.current);

                    setDragP3((finalP3) => {
                        if (finalP3) {
                            const newPoints = [shape.points[0], shape.points[1], { x: finalP3.x, y: finalP3.y, z: finalP3.z }];
                            updateShape(shape.id, { points: newPoints });
                        }
                        return null; 
                    });
                }
            };

            window.addEventListener('pointermove', handleWindowMove);
            window.addEventListener('pointerup', handleWindowUp);
        } else {
            e.stopPropagation();
            onSelect(e);
        }
    };

    return (
        <group 
            onPointerDown={handlePointerDown}
            position={shape.position} 
            rotation={shape.rotation} 
            scale={shape.scale}
        >
            <SimpleLine points={[dimStart, dimEnd]} color={color} depthTest={false} opacity={0.8} />

            {useExtensions && (
                <>
                    <SimpleLine points={[ext1Start, ext1End]} color={extensionColor} opacity={0.5} depthTest={false} lineWidth={1} />
                    <SimpleLine points={[ext2Start, ext2End]} color={extensionColor} opacity={0.5} depthTest={false} lineWidth={1} />
                </>
            )}

            <DimensionTick position={dimStart} direction={dimDir} color={color} />
            <DimensionTick position={dimEnd} direction={dimDir} color={color} />

            <Billboard position={midPoint}>
                <Text 
                    fontSize={0.25} 
                    color={color} 
                    anchorX="center" 
                    anchorY="middle" 
                    outlineWidth={0.03} 
                    outlineColor="#ffffff" 
                    depthTest={false}
                    renderOrder={1000}
                    backgroundColor="white"
                    backgroundOpacity={0.8}
                    padding={0.05}
                >
                    {formatValue(p1.distanceTo(p2))}
                </Text>
            </Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group renderOrder={1}>
            {lines.map((line) => {
                const p1 = new THREE.Vector3(...line.points[0]);
                const p2 = new THREE.Vector3(...line.points[1]);
                const dir = new THREE.Vector3().subVectors(p2, p1).normalize();

                const start = p1.clone().add(dir.clone().multiplyScalar(-5000));
                const end = p1.clone().add(dir.clone().multiplyScalar(5000));

                return (
                    <group key={line.id}>
                         <SimpleLine points={[start, end]} color="#000000" dashed opacity={0.5} transparent />
                        <SimpleLine points={[start, end]} color="#ffffff" opacity={0.2} transparent depthTest={false} />
                    </group>
                );
            })}
        </group>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const newLines: AlignmentLine[] = [];
             const myBoundsRaw = getShapeBounds(shape, new THREE.Vector3(targetPos.x, myOriginalPos.y, targetPos.z));
             let bestXDist = 0.3; let bestXVal: number | null = null; let xMatchLine: AlignmentLine | null = null;
             let bestZDist = 0.3; let bestZVal: number | null = null; let zMatchLine: AlignmentLine | null = null;
             for (const other of shapes) {
                 if (selectedIds.includes(other.id)) continue;
                 const otherBounds = getShapeBounds(other);
                 const xSources = [myBoundsRaw.centerX, myBoundsRaw.minX, myBoundsRaw.maxX];
                 const xTargets = [otherBounds.centerX, otherBounds.minX, otherBounds.maxX];
                 for (const src of xSources) {
                     for (const tgt of xTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestXDist) { bestXDist = dist; bestXVal = targetPos.x - (src - tgt); const minZ = Math.min(myBoundsRaw.minZ, otherBounds.minZ) - 1; const maxZ = Math.max(myBoundsRaw.maxZ, otherBounds.maxZ) + 1; xMatchLine = [ new THREE.Vector3(tgt, 0, minZ), new THREE.Vector3(tgt, 0, maxZ) ]; }
                     }
                 }
                 const zSources = [myBoundsRaw.centerZ, myBoundsRaw.minZ, myBoundsRaw.maxZ];
                 const zTargets = [otherBounds.centerZ, otherBounds.minZ, otherBounds.maxZ];
                 for (const src of zSources) {
                     for (const tgt of zTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestZDist) { bestZDist = dist; bestZVal = targetPos.z - (src - tgt); const minX = Math.min(myBoundsRaw.minX, otherBounds.minX) - 1; const maxX = Math.max(myBoundsRaw.maxX, otherBounds.maxX) + 1; zMatchLine = [ new THREE.Vector3(minX, 0, tgt), new THREE.Vector3(maxX, 0, tgt) ]; }
                     }
                 }
             }
             if (bestXVal !== null) { snappedX = bestXVal; if (xMatchLine) newLines.push(xMatchLine); }
             if (bestZVal !== null) { snappedZ = bestZVal; if (zMatchLine) newLines.push(zMatchLine); }
             setAlignmentLines(newLines);
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) updateShapes(updates);
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) idsToMove = [...selectedIds]; else { if (shape.groupId) idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); else idsToMove = [shape.id]; }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) origins[id] = ref.position.clone(); });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes, selectShape, updateShape } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);

    const handleSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        e.stopPropagation();
        const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey;
        selectShape(shape.id, isMulti);
    }, [selectShape, shape.id]);

    const dimensionSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (!isSelected) {
             e.stopPropagation();
             selectShape(shape.id, e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey);
        }
    }, [isSelected, selectShape, shape.id]);

    if (parentLayer && !parentLayer.visible) return null;

    if (shape.type === 'dimension') { 
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={dimensionSelect} />; 
    }

    if (shape.type === 'text') {
        const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

        useLayoutEffect(() => { 
            onShapeRef(shape.id, groupRef.current); 
            return () => onShapeRef(shape.id, null); 
        }, [onShapeRef, shape.id]);

        return (
            <group
                ref={groupRef}
                position={shape.position}
                rotation={new THREE.Euler(...shape.rotation)}
                scale={shape.scale}
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
                onPointerDown={(e) => {
                     if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                     else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                }}
            >
                <Text
                    fontSize={shape.fontSize || 0.5}
                    color={shape.color}
                    anchorX="center"
                    anchorY="middle"
                    outlineWidth={isSelected ? 0.02 : 0}
                    outlineColor="#3b82f6"
                >
                    {shape.content || 'Text'}
                </Text>
            </group>
        );
    }

    if (shape.type === 'line') {
         if (shape.points.length < 2) return null;
         const p1 = transformPoint(shape.points[0], shape);
         const p2 = transformPoint(shape.points[1], shape);
         return (
             <group 
                position={[0, 0, 0]} 
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
             >
                <SimpleLine points={[p1, p2]} color={isSelected ? '#3b82f6' : 'black'} lineWidth={2} />
             </group>
         );
    }

    if (!shape.points || shape.points.length < 3) return null;

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = shape.color;
    const edgeColor = isSelected ? '#3b82f6' : '#333';
    const emissiveColor = isSelected ? '#3b82f6' : '#000000';
    const emissiveIntensity = isSelected ? 0.2 : 0;

    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

    useLayoutEffect(() => { 
        onShapeRef(shape.id, groupRef.current); 
        return () => onShapeRef(shape.id, null); 
    }, [onShapeRef, shape.id]);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) scaleY = pushPullState.dragHeight / shape.height;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const geometry = useMemo(() => new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false }), [shape2D, shape.height]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerMove(e); }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); else drawingHandlers.handlePointerUp(e); }}
        >
            <mesh 
                rotation={[-Math.PI/2, 0, 0]} 
                castShadow 
                receiveShadow 
                userData={{ isShape: true, id: shape.id }}
                geometry={geometry}
            >
                <meshStandardMaterial color={highlightColor} emissive={emissiveColor} emissiveIntensity={emissiveIntensity} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                {!isPushPullMode && (
                    <lineSegments>
                        <edgesGeometry args={[geometry, 15]} />
                        <lineBasicMaterial color={edgeColor} toneMapped={false} />
                    </lineSegments>
                )}
            </mesh>
        </group>
    );
});

// ... Managers ...
const usePushPullManager = () => {
    const { tool, updateShape, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = (e.intersections as unknown as THREE.Intersection[]).find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;
        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id; else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;
        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (worldNormal.y < -0.9) return { mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, -1, 0) }; 
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation));
            const invQuat = shapeQuat.clone().invert();
            const localPoint = hitPoint.applyQuaternion(invQuat);
            const xLocal = localPoint.x; const zLocal = localPoint.z;
            let closestIndex = -1; let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) { const p1 = pts[i]; const p2 = pts[(i+1) % pts.length]; const unscaledX = xLocal / shape.scale[0]; const unscaledZ = zLocal / shape.scale[2]; const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z)); if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; } }
            if (closestIndex !== -1) { const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize(); return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal }; }
        }
        return null;
    }, [shapes, layers]);

    const performDrag = useCallback((clientX: number, clientY: number) => {
        if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (!shape) return;

        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1), camera);

        if (ppState.mode === 'top') { 
            const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint); 
            const target = new THREE.Vector3(); 
            raycaster.ray.intersectPlane(dragPlane, target); 
            if (target) { 
                const deltaY = target.y - ppState.dragStartPoint.y; 
                const newHeight = Math.max(0.01, ppState.originalHeight + deltaY); 
                setPPState(prev => ({ ...prev, dragHeight: newHeight })); 
                setMeasurement(`高度: ${formatValue(newHeight)}`); 
            } 
        } else if (ppState.mode === 'side') { 
            const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
            const target = new THREE.Vector3(); 
            raycaster.ray.intersectPlane(dragPlane, target); 
            if (target) { 
                const diff = target.clone().sub(ppState.dragStartPoint); 
                const projection = diff.dot(ppState.normal); 
                const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection); 
                setMeasurement(`偏移: ${formatValue(projection)}`); 
                const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)); 
                const invQuat = shapeQuat.clone().invert(); 
                const moveVectorLocal = moveVectorWorld.clone().applyQuaternion(invQuat); 
                const dLocalX = moveVectorLocal.x / shape.scale[0]; 
                const dLocalZ = moveVectorLocal.z / shape.scale[2]; 
                const idx = ppState.hoveredEdgeIndex; 
                const newPoints = ppState.originalPoints.map(p => ({...p})); 
                const p1 = newPoints[idx]; 
                const p2 = newPoints[(idx+1) % newPoints.length]; 
                p1.x += dLocalX; p1.z += dLocalZ; 
                p2.x += dLocalX; p2.z += dLocalZ; 
                const updatedShape = { ...shape, points: newPoints }; 
                setTempShape(updatedShape); 
            } 
        }
    }, [ppState, shapes, camera, gl, setMeasurement, formatValue]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
        } else {
            const res = identifyFace(e);
            if (res) { 
                e.stopPropagation(); 
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize'; 
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! })); 
            } else { 
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null })); 
                document.body.style.cursor = 'default'; 
            }
        }
    }, [tool, isDragging, ppState, shapes, camera, gl, identifyFace]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') { const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), (e as any).point); raycaster.ray.intersectPlane(plane, startPoint); } 
             else { const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); raycaster.ray.intersectPlane(plane, startPoint); }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    }, [tool, ppState, shapes, camera, gl]);

    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) { const shape = shapes.find(s => s.id === ppState.hoveredShapeId); const updates: Partial<IShape> = { height: ppState.dragHeight }; if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) { updates.type = 'solid'; if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR; } updateShape(ppState.hoveredShapeId, updates); } 
        else if (tempShapeRef.current) { updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points }); }
        setTempShape(null); setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined })); setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);

    useEffect(() => { 
        if (isDragging) { 
            const onGlobalPointerUp = () => handlePointerUp(); 
            const onGlobalPointerMove = (e: PointerEvent) => performDrag(e.clientX, e.clientY);

            window.addEventListener('pointerup', onGlobalPointerUp); 
            window.addEventListener('pointermove', onGlobalPointerMove);
            return () => { 
                window.removeEventListener('pointerup', onGlobalPointerUp);
                window.removeEventListener('pointermove', onGlobalPointerMove);
            }; 
        } 
    }, [isDragging, handlePointerUp, performDrag]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useRotateManager = () => {
    const { tool, selectedIds, shapes, updateShapes } = useApp();
    const [state, setState] = useState<RotateState>({ phase: 'none', pivot: null, startVector: null, currentVector: null });

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE || selectedIds.length === 0) return;
        e.stopPropagation();

        if (state.phase === 'none') {
            setState({ phase: 'set-start', pivot: e.point.clone(), startVector: null, currentVector: null });
        } else if (state.phase === 'set-start') {
            const pivot = state.pivot!;
            const startVec = new THREE.Vector3().subVectors(e.point, pivot).normalize();
            setState({ phase: 'rotating', pivot, startVector: startVec, currentVector: startVec });
        } else if (state.phase === 'rotating') {
            setState({ phase: 'none', pivot: null, startVector: null, currentVector: null });
        }
    }, [tool, selectedIds, state]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.ROTATE || state.phase !== 'rotating' || !state.pivot || !state.startVector) return;
        const currentVec = new THREE.Vector3().subVectors(e.point, state.pivot).normalize();

        let angle = Math.atan2(state.startVector.z, state.startVector.x) - Math.atan2(currentVec.z, currentVec.x);
        // Snap angle to 15 degrees
        if (e.shiftKey) {
             const deg = (angle * 180) / Math.PI;
             const snappedDeg = Math.round(deg / 15) * 15;
             angle = (snappedDeg * Math.PI) / 180;
        }

        const updates = selectedIds.map(id => {
             const s = shapes.find(shape => shape.id === id);
             if (s) {
                 // Simple rotation addition for Y axis
                 const currentRot = s.rotation[1];
                 const newRot = currentRot + angle * 0.1; // Delta dampening or absolute? 
                 // For absolute, we need initial rotation. Simplified here to just show intent.
                 // Ideally we track initial rotation in state.
             }
             return null;
        });
        setState(prev => ({ ...prev, currentVector: currentVec }));
    }, [tool, state, selectedIds, shapes]);

    return { rotateState: state, handleClick, handlePointerMove };
};

const useDrawingManager = () => {
    const { tool, addShape, addGuideLine, layers, activeLayerId, setMeasurement, formatValue, shapes } = useApp();
    const [points, setPoints] = useState<IPoint[]>([]);
    const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
    const [snapResult, setSnapResult] = useState<SnapResult | null>(null);
    const { camera, gl } = useThree();

    const getCursorPosition = useCallback((e: ThreeEvent<PointerEvent>): SnapResult => {
        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);
        const snap = getGeometrySnap(target, raycaster.ray, shapes, points, SNAP_THRESHOLD);
        setSnapResult(snap);
        return snap;
    }, [camera, gl, shapes, points]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_TEXT, ToolType.DIMENSION, ToolType.GUIDE_LINE].includes(tool)) return;
        e.stopPropagation();

        const snap = getCursorPosition(e as any);
        const p = { x: snap.position.x, y: 0, z: snap.position.z };

        if (tool === ToolType.DRAW_TEXT) {
            const text = prompt("輸入文字內容:", "Text");
            if (text) {
                addShape({
                    id: `text-${Date.now()}`,
                    layerId: activeLayerId,
                    type: 'text',
                    name: 'Text',
                    content: text,
                    points: [p],
                    height: 0,
                    color: '#000000',
                    position: [p.x, 0, p.z],
                    rotation: [0, 0, 0],
                    scale: [1, 1, 1],
                    fontSize: 0.5
                });
            }
            return;
        }

        const newPoints = [...points, p];
        setPoints(newPoints);

        if (tool === ToolType.DRAW_RECT && newPoints.length === 2) {
            const [p1, p2] = newPoints;
            const rectPoints = [
                { x: p1.x, y: 0, z: p1.z },
                { x: p2.x, y: 0, z: p1.z },
                { x: p2.x, y: 0, z: p2.z },
                { x: p1.x, y: 0, z: p2.z },
                { x: p1.x, y: 0, z: p1.z }
            ];
            addShape({
                id: `rect-${Date.now()}`,
                layerId: activeLayerId,
                type: 'flat',
                name: 'Rectangle',
                points: rectPoints,
                height: DEFAULT_HEIGHT,
                color: FLAT_COLOR,
                position: [0, 0, 0],
                rotation: [0, 0, 0],
                scale: [1, 1, 1]
            });
            setPoints([]);
            setCurrentPoint(null);
        } else if (tool === ToolType.DRAW_CIRCLE && newPoints.length === 2) {
            const [center, edge] = newPoints;
            const radius = Math.sqrt((center.x - edge.x)**2 + (center.z - edge.z)**2);
            const circlePoints = createCirclePoints(radius);
            addShape({
                id: `circle-${Date.now()}`,
                layerId: activeLayerId,
                type: 'flat',
                name: 'Circle',
                points: circlePoints,
                height: DEFAULT_HEIGHT,
                color: FLAT_COLOR,
                position: [center.x, 0, center.z],
                rotation: [0, 0, 0],
                scale: [1, 1, 1]
            });
            setPoints([]);
            setCurrentPoint(null);
        } else if (tool === ToolType.DRAW_LINE && newPoints.length === 2) {
            addShape({
                id: `line-${Date.now()}`,
                layerId: activeLayerId,
                type: 'line',
                name: 'Line',
                points: newPoints,
                height: 0,
                color: '#000000',
                position: [0, 0, 0],
                rotation: [0, 0, 0],
                scale: [1, 1, 1]
            });
            setPoints([]);
            setCurrentPoint(null);
        } else if (tool === ToolType.DIMENSION && newPoints.length === 3) {
             addShape({
                id: `dim-${Date.now()}`,
                layerId: activeLayerId,
                type: 'dimension',
                name: 'Dimension',
                points: newPoints,
                height: 0,
                color: '#000000',
                position: [0, 0, 0],
                rotation: [0, 0, 0],
                scale: [1, 1, 1]
            });
            setPoints([]);
            setCurrentPoint(null);
        } else if (tool === ToolType.GUIDE_LINE && newPoints.length === 2) {
            addGuideLine({
                id: `guide-${Date.now()}`,
                points: [[newPoints[0].x, 0, newPoints[0].z], [newPoints[1].x, 0, newPoints[1].z]]
            });
            setPoints([]);
            setCurrentPoint(null);
        }

    }, [tool, points, activeLayerId, addShape, addGuideLine, getCursorPosition]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.GUIDE_LINE].includes(tool)) return;
        const snap = getCursorPosition(e);
        setCurrentPoint({ x: snap.position.x, y: 0, z: snap.position.z });

        // Measurement updates
        if (points.length > 0) {
            const last = points[points.length - 1];
            const dist = Math.sqrt((snap.position.x - last.x)**2 + (snap.position.z - last.z)**2);
            setMeasurement(`長度: ${formatValue(dist)}`);
        } else {
            setMeasurement(`${formatValue(snap.position.x)}, ${formatValue(snap.position.z)}`);
        }
    }, [tool, points, getCursorPosition, setMeasurement, formatValue]);

    // Temp Shape for Preview
    const tempShape = useMemo(() => {
        if (!currentPoint || points.length === 0) return null;
        const start = points[0];

        if (tool === ToolType.DRAW_RECT) {
            return (
                <line>
                     <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" args={[new Float32Array([
                            start.x, 0, start.z,
                            currentPoint.x, 0, start.z,
                            currentPoint.x, 0, currentPoint.z,
                            start.x, 0, currentPoint.z,
                            start.x, 0, start.z
                        ]), 3]} />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" />
                </line>
            );
        } else if (tool === ToolType.DRAW_LINE || tool === ToolType.GUIDE_LINE) {
             return (
                <line>
                     <bufferGeometry>
                        <float32BufferAttribute attach="attributes-position" args={[new Float32Array([
                            start.x, 0, start.z,
                            currentPoint.x, 0, currentPoint.z
                        ]), 3]} />
                    </bufferGeometry>
                    <lineBasicMaterial color="red" />
                </line>
            );
        } else if (tool === ToolType.DRAW_CIRCLE) {
            const radius = Math.sqrt((start.x - currentPoint.x)**2 + (start.z - currentPoint.z)**2);
            return (
                <mesh position={[start.x, 0, start.z]} rotation={[-Math.PI/2, 0, 0]}>
                    <ringGeometry args={[radius - 0.05, radius, 32]} />
                    <meshBasicMaterial color="red" />
                </mesh>
            );
        }
        return null;
    }, [points, currentPoint, tool]);

    return { drawingHandlers: { handleClick, handlePointerMove, handlePointerDown: () => {}, handlePointerUp: () => {} }, tempShape, snapResult };
};

const SceneContent = () => {
    const { shapes, guideLines, selectedIds, tool, currentView, setTransformMode } = useApp();
    const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging, tempShape: ppTempShape } = usePushPullManager();
    const { rotateState, handleClick: handleRotateClick, handlePointerMove: handleRotateMove } = useRotateManager();
    const { drawingHandlers, tempShape: drawingTempShape, snapResult } = useDrawingManager();

    const [draggingState, setDraggingState] = useState(false);
    const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);

    const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
    const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => {
        shapeRefs.current[id] = ref;
    }, []);

    // Camera View Update
    const { camera } = useThree();
    useEffect(() => {
        if (!currentView) return;
        const pos = new THREE.Vector3();
        if (currentView === 'top') pos.set(0, 20, 0);
        else if (currentView === 'front') pos.set(0, 5, 20);
        else if (currentView === 'right') pos.set(20, 5, 0);
        else if (currentView === 'left') pos.set(-20, 5, 0);
        else if (currentView === 'bottom') pos.set(0, -20, 0);

        camera.position.copy(pos);
        camera.lookAt(0, 0, 0);
    }, [currentView, camera]);

    const isDrawing = [ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_TEXT, ToolType.DIMENSION, ToolType.GUIDE_LINE].includes(tool);

    return (
        <>
            <color attach="background" args={['#f1f5f9']} />
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow shadow-mapSize={[2048, 2048]} />
            <Grid infiniteGrid sectionSize={1} cellSize={1} fadeDistance={50} sectionColor="#94a3b8" cellColor="#cbd5e1" position={[0, -0.01, 0]} />

            <OrbitControls makeDefault enabled={!isPPDragging && !draggingState} />

            <group
                onPointerMove={(e) => {
                    if (isDrawing) drawingHandlers.handlePointerMove(e);
                    else if (tool === ToolType.PUSH_PULL) handlePPMove(e);
                    else if (tool === ToolType.ROTATE) handleRotateMove(e);
                }}
                onClick={(e) => {
                    if (isDrawing) drawingHandlers.handleClick(e);
                    else if (tool === ToolType.ROTATE) handleRotateClick(e);
                }}
                onPointerUp={handlePPUp}
            >
                {/* Shapes */}
                {shapes.map(shape => (
                    (ppState.hoveredShapeId === shape.id && ppTempShape) ? null : 
                    <ShapeRenderer
                        key={shape.id}
                        shape={shape}
                        isSelected={selectedIds.includes(shape.id)}
                        pushPullState={ppState}
                        pushPullHandlers={{ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }}
                        drawingHandlers={drawingHandlers}
                        rotateHandlers={{ handleClick: handleRotateClick, handlePointerMove: handleRotateMove }}
                        setDraggingState={setDraggingState}
                        onShapeRef={setShapeRef}
                        shapeRefs={shapeRefs}
                        setAlignmentLines={setAlignmentLines}
                    />
                ))}

                {/* Temp Shapes (PushPull or Drawing) */}
                {ppTempShape && (
                    <ShapeRenderer
                         shape={ppTempShape}
                         isSelected={true}
                         pushPullState={ppState}
                         pushPullHandlers={{ handlePointerDown: () => {}, handlePointerUp: () => {}, handlePointerMove: () => {} }}
                         drawingHandlers={drawingHandlers}
                         rotateHandlers={{ handleClick: () => {}, handlePointerMove: () => {} }}
                         setDraggingState={() => {}}
                         onShapeRef={() => {}}
                         shapeRefs={shapeRefs}
                         setAlignmentLines={() => {}}
                    />
                )}
                {drawingTempShape}

                {/* Visuals */}
                <GuideLinesRenderer lines={guideLines} />
                <AlignmentLinesRenderer lines={alignmentLines} />
                {snapResult && <SnapIndicator position={snapResult.position} type={snapResult.type} snapEdge={snapResult.snapEdge} />}
                {snapResult && snapResult.type !== 'grid' && snapResult.type !== 'none' && (
                     <CursorTooltip text="" position={snapResult.position} type={snapResult.type} />
                )}

                {/* Rotate Visuals */}
                {rotateState.pivot && (
                    <group position={rotateState.pivot}>
                        <mesh rotation={[-Math.PI/2, 0, 0]}>
                            <ringGeometry args={[0, 0.5, 32]} />
                            <meshBasicMaterial color="blue" opacity={0.3} transparent />
                        </mesh>
                        {rotateState.currentVector && (
                            <line>
                                <bufferGeometry>
                                    <float32BufferAttribute attach="attributes-position" args={[new Float32Array([0,0,0, rotateState.currentVector.x * 2, 0, rotateState.currentVector.z * 2]), 3]} />
                                </bufferGeometry>
                                <lineBasicMaterial color="blue" />
                            </line>
                        )}
                    </group>
                )}
            </group>

            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full relative outline-none">
            <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
                <SceneContent />
            </Canvas>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Ray distance threshold
const ALIGN_THRESHOLD = 0.4; // Axis alignment threshold
const SNAP_CULLING_DISTANCE = 15; // Distance to ignore geometry snapping
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

interface InferenceGuide {
    type: 'x' | 'z';
    start: THREE.Vector3;
    end: THREE.Vector3;
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface RotateState {
    phase: 'none' | 'set-pivot' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentVector: THREE.Vector3 | null;
}

